// --- Component Schema & Setup ---



export type KeepingUpJonesesProps = Record<string, any>;

const KeepingUpJoneses: React.FC<KeepingUpJonesesProps> = ({
  backgroundColor = "#F5F2EB",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryTextColor = "#111111",
  highlightColor = "#EA4C23",
  line1Text = "Better vacations,",
  line2Text = "nicer cars,",
  line3Text = "bigger homes.",
  line4Text = "These are",
  line5Text = "the Joneses",
  line6Text = "most people are",
  line7Text = "trying to keep",
  line8Text = "up with.",
  titleFontSize = 54,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety parsing for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing ratios
  const isVertical = height > width;
  const scaledFontSize = (titleFontSize / 1920) * (isVertical ? width * 1.8 : width);

  // Elite spring physical presets for snappy, natural assembly motion
  const springConfig = {
    damping: 14,
    mass: 0.65,
    stiffness: 95,
  };

  // Text Entrance Springs
  const s1 = spring({ frame: frame - 12, fps, config: springConfig });
  const s2 = spring({ frame: frame - 24, fps, config: springConfig });
  const s3 = spring({ frame: frame - 36, fps, config: springConfig });
  const s4 = spring({ frame: frame - 48, fps, config: springConfig });
  const s5 = spring({ frame: frame - 60, fps, config: springConfig });
  const s6 = spring({ frame: frame - 72, fps, config: springConfig });
  const s7 = spring({ frame: frame - 84, fps, config: springConfig });
  const s8 = spring({ frame: frame - 96, fps, config: springConfig });

  // Grid Element Entrance Springs
  const sArch = spring({ frame: frame - 15, fps, config: springConfig });
  const sCar = spring({ frame: frame - 38, fps, config: springConfig });
  const sHouse = spring({ frame: frame - 62, fps, config: springConfig });
  const sDeco = spring({ frame: frame - 85, fps, config: springConfig });

  // Organic Idle Oscillations (only starts once active to avoid jumps)
  const idlePalm = frame > 40 ? Math.sin((frame - 40) * 0.035) * 3 : 0;
  const idleCar = frame > 65 ? Math.sin((frame - 65) * 0.04) * 4 : 0;
  const idleHouse = frame > 85 ? Math.cos((frame - 85) * 0.03) * 2.5 : 0;

  // Reusable text line renderer with container masking
  const renderLine = (text: string, springVal: number, isHighlight: boolean = false) => {
    const opacity = interpolate(springVal, [0, 0.7], [0, 1], { extrapolateRight: "clamp" });
    const translateY = interpolate(springVal, [0, 1], [scaledFontSize * 0.8, 0], { extrapolateRight: "clamp" });

    return (
      <div
        style={{
          overflow: "hidden",
          height: scaledFontSize * 1.35,
          display: "flex",
          alignItems: "center",
          opacity,
          transform: `translateY(${translateY}px)`,
          transition: "none",
        }}
      >
        <span
          style={{
            fontFamily: dmSansFamily,
            fontWeight: 800,
            fontSize: scaledFontSize,
            lineHeight: 1.1,
            color: isHighlight ? highlightColor : primaryTextColor,
            letterSpacing: "-0.02em",
          }}
        >
          {text}
        </span>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", flexDirection: isVertical ? "column" : "row" }}>
      
      {/* LEFT SIDE: Editorial Typography */}
      <div
        style={{
          width: isVertical ? "100%" : "46%",
          height: isVertical ? "40%" : "100%",
          padding: isVertical ? `${height * 0.05}px ${width * 0.08}px` : `${height * 0.1}px ${width * 0.06}px`,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          boxSizing: "border-box",
          zIndex: 10,
        }}
      >
        {renderLine(line1Text, s1)}
        {renderLine(line2Text, s2)}
        {renderLine(line3Text, s3)}
        {renderLine(line4Text, s4)}
        {renderLine(line5Text, s5, true)}
        {renderLine(line6Text, s6)}
        {renderLine(line7Text, s7)}
        {renderLine(line8Text, s8)}
      </div>

      {/* RIGHT SIDE: Geometric Grid Assembly */}
      <div
        style={{
          width: isVertical ? "90%" : "54%",
          height: isVertical ? "55%" : "100%",
          margin: isVertical ? `0 auto ${height * 0.05}px` : "0",
          position: "relative",
          boxSizing: "border-box",
        }}
      >
        <div style={{ position: "absolute", top: "10%", bottom: "10%", left: "5%", right: "5%" }}>
          
          {/* Tile 1: Palm Tree Arch (Better Vacations) */}
          <div
            style={{
              position: "absolute",
              top: "0%",
              left: "0%",
              width: "60%",
              height: "50%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sArch, [0, 0.8], [0, 1]),
              transform: `scale(${interpolate(sArch, [0, 1], [0.8, 1])}) translateY(${idlePalm}px)`,
              transformOrigin: "bottom center",
              transition: "none",
              zIndex: 3,
            }}
          >
            <div
              style={{
                width: "100%",
                height: "100%",
                borderRadius: `${Math.min(width, height) * 0.22}px ${Math.min(width, height) * 0.22}px 0 0`,
                overflow: "hidden",
                display: "flex",
                boxShadow: "0 10px 30px rgba(0,0,0,0.08)",
              }}
            >
              <div style={{ width: "50%", backgroundColor: highlightColor }} />
              <div style={{ width: "50%", backgroundColor: "#FFFFFF", position: "relative" }}>
                <PalmTreeSvg />
              </div>
            </div>
          </div>

          {/* Tile 2: Solid Black Block */}
          <div
            style={{
              position: "absolute",
              top: "0%",
              left: "60%",
              width: "40%",
              height: "50%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sDeco, [0, 0.8], [0, 1]),
              transform: `scale(${interpolate(sDeco, [0, 1], [0.9, 1])})`,
              transition: "none",
              zIndex: 1,
            }}
          >
            <div style={{ width: "100%", height: "100%", backgroundColor: "#111111" }} />
          </div>

          {/* Tile 3: Sleek Luxury Car (Nicer Cars) */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "0%",
              width: "60%",
              height: "25%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sCar, [0, 0.8], [0, 1]),
              transform: `translateX(${interpolate(sCar, [0, 1], [80, 0])}px) translateY(${idleCar}px)`,
              transition: "none",
              zIndex: 4,
            }}
          >
            <LuxuryCarSvg />
          </div>

          {/* Tile 4: Solid Orange Square */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "60%",
              width: "40%",
              height: "25%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sDeco, [0, 0.8], [0, 1]),
              transform: `scale(${interpolate(sDeco, [0, 1], [0.9, 1])})`,
              transition: "none",
              zIndex: 2,
            }}
          >
            <div style={{ width: "100%", height: "100%", backgroundColor: highlightColor }} />
          </div>

          {/* Tile 5a: Solid Orange Rect (Bottom-Left support) */}
          <div
            style={{
              position: "absolute",
              top: "75%",
              left: "0%",
              width: "30%",
              height: "25%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sDeco, [0, 0.8], [0, 1]),
              transform: `scale(${interpolate(sDeco, [0, 1], [0.9, 1])})`,
              transition: "none",
              zIndex: 1,
            }}
          >
            <div style={{ width: "100%", height: "100%", backgroundColor: highlightColor }} />
          </div>

          {/* Tile 5b: Curved Black Graphic Block */}
          <div
            style={{
              position: "absolute",
              top: "75%",
              left: "30%",
              width: "30%",
              height: "25%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sDeco, [0, 0.8], [0, 1]),
              transform: `scale(${interpolate(sDeco, [0, 1], [0.9, 1])})`,
              transition: "none",
              zIndex: 2,
            }}
          >
            <CurvedBlock color="#111111" />
          </div>

          {/* Tile 6: Architectural Modern House (Bigger Homes) */}
          <div
            style={{
              position: "absolute",
              top: "65%",
              left: "50%",
              width: "50%",
              height: "35%",
              padding: "10px",
              boxSizing: "border-box",
              opacity: interpolate(sHouse, [0, 0.8], [0, 1]),
              transform: `translateY(${interpolate(sHouse, [0, 1], [60, 0]) + idleHouse}px)`,
              transition: "none",
              zIndex: 5,
            }}
          >
            <div style={{ width: "100%", height: "100%", borderRadius: "4px", overflow: "hidden", boxShadow: "0 15px 35px rgba(0,0,0,0.12)" }}>
              <ModernHouse />
            </div>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

